static int height(struct TreeNode *node) {
  if (!node) return 0;
  int l = height(node->left);
  if (l == -1) return -1;
  int r = height(node->right);
  if (r == -1) return -1;
  if (abs(l - r) > 1) return -1;
  return 1 + (l > r ? l : r);
}

bool isBalanced(struct TreeNode *root) {
  return height(root) != -1;
}

class Solution {
  int height(TreeNode *node) {
    if (!node) return 0;
    int l = height(node->left);
    if (l == -1) return -1;
    int r = height(node->right);
    if (r == -1) return -1;
    if (abs(l - r) > 1) return -1;
    return 1 + max(l, r);
  }

public:
  bool isBalanced(TreeNode *root) { return height(root) != -1; }
};

func isBalanced(root *TreeNode) bool {
	var height func(node *TreeNode) int
	height = func(node *TreeNode) int {
		if node == nil {
			return 0
		}
		l := height(node.Left)
		if l == -1 {
			return -1
		}
		r := height(node.Right)
		if r == -1 {
			return -1
		}
		d := l - r
		if d < 0 {
			d = -d
		}
		if d > 1 {
			return -1
		}
		if l > r {
			return 1 + l
		}
		return 1 + r
	}
	return height(root) != -1
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private int height(TreeNode node) {
    if (node == null) return 0;
    int l = height(node.left);
    if (l == -1) return -1;
    int r = height(node.right);
    if (r == -1) return -1;
    if (Math.abs(l - r) > 1) return -1;
    return 1 + Math.max(l, r);
  }

  public boolean isBalanced(TreeNode root) {
    return height(root) != -1;
  }
}

class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        def height(node: Optional[TreeNode]) -> int:
            if node is None:
                return 0
            l = height(node.left)
            if l == -1:
                return -1
            r = height(node.right)
            if r == -1:
                return -1
            if abs(l - r) > 1:
                return -1
            return 1 + max(l, r)

        return height(root) != -1

impl Solution {
  pub fn is_balanced(root: Option<Box<TreeNode>>) -> bool {
    fn height(node: &Option<Box<TreeNode>>) -> i32 {
      if let Some(n) = node {
        let l = height(&n.left);
        if l == -1 {
          return -1;
        }
        let r = height(&n.right);
        if r == -1 {
          return -1;
        }
        if (l - r).abs() > 1 {
          return -1;
        }
        1 + l.max(r)
      } else {
        0
      }
    }
    height(&root) != -1
  }
}

const isBalanced = (root: TreeNode | null): boolean => {
  const height = (node: TreeNode | null): number => {
    if (!node) return 0;
    const l = height(node.left);
    if (l === -1) return -1;
    const r = height(node.right);
    if (r === -1) return -1;
    if (Math.abs(l - r) > 1) return -1;
    return 1 + Math.max(l, r);
  };
  return height(root) !== -1;
};
